	<script type="text/javascript">


		function YahooAdsub() 
			{

				dummyimage = new Image();
				dummyimage.src = 'http://www.niche-mania.com/AdTracker.php?' + 'dmn=<?=$_SERVER["HTTP_HOST"];?>' + '&' + 'src=' + document.location + '&' + 'tgt=' + window.status.substring(6) + '&' + 'wdh=' + event.srcElement.width + '&' + 'hgt=' + event.srcElement.height + '&' + 'typ=regular' + '&' + 'ppc=Yahoo';

			}		

		function GoogleAdsub() 
			{
				if (window.status.indexOf('go to') == 0) 
					{
						dummyimage = new Image();
						dummyimage.src = 'http://www.niche-mania.com/AdTracker.php?' + 'dmn=<?=$_SERVER["HTTP_HOST"];?>' + '&' + 'src=' + document.location + '&' + 'tgt=' + window.status.substring(6) + '&' + 'wdh=' + event.srcElement.width + '&' + 'hgt=' + event.srcElement.height + '&' + 'typ=regular' + '&' + 'ppc=Google';
					}
		
				if (window.status.indexOf('View ads about') == 0) 
					{
						dummyimage = new Image();
						dummyimage.src = 'http://www.niche-mania.com/AdTracker.php?' + 'dmn=<?=$_SERVER["HTTP_HOST"];?>' + '&' + 'src=' + document.location + '&' + 'tgt=' + window.status.substring(15) + '&' + 'wdh=' + event.srcElement.width + '&' + 'hgt=' + event.srcElement.height + '&' + 'typ=link' + '&' + 'ppc=Google';
					}
			}

		function GoogleSearchsub() 
			{
				dummyimage = new Image();
				dummyimage.src = 'http://www.niche-mania.com/AdTracker.php?' + 'dmn=<?=$_SERVER["HTTP_HOST"];?>' + '&' + 'src=' + document.location + '&' + 'tgt=' + event.srcElement.form.q.value + '&' + 'typ=search' + '&' + 'ppc=Google';
			}

		var iframes;
		
		iframes = document.getElementsByTagName("iframe");
		
		for (var i = 0; i < iframes.length; i++) 
			{
				if(iframes[i].src.indexOf('googlesyndication') > -1) 
					{
						iframes[i].attachEvent("onfocus", GoogleAdsub);
					}
				if(iframes[i].src.indexOf('overture') > -1) 
					{
						iframes[i].attachEvent("onfocus", YahooAdsub);
					}	
							
			}

		var forms;
		
		forms = document.getElementsByTagName("form");
		
		for (var i = 0; i < forms.length; i++) 
			{
				if(forms[i].action == "http://www.google.com/custom") 
					{
						forms[i].sa.attachEvent("onclick", GoogleSearchsub);
					}
			}
	</script>